ALTER TABLE public.institution_resources ADD COLUMN visibility text NOT NULL DEFAULT 'restricted' CHECK(visibility IN ('public','restricted'));
UPDATE public.institution_resources SET visibility='public' WHERE status='published';
CREATE FUNCTION public.manages_institution_resource(_inst uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.has_role(auth.uid(),'admin'),false) OR (coalesce(public.institution_role_of(_inst)='direccion',false) AND public.can_edit_institution_publication(_inst)); $$;
REVOKE ALL ON FUNCTION public.manages_institution_resource(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manages_institution_resource(uuid) TO authenticated;
CREATE TABLE public.institution_resource_grants(resource_id uuid NOT NULL REFERENCES public.institution_resources(id),institution_id uuid NOT NULL REFERENCES public.institutions(id),can_read boolean NOT NULL DEFAULT true,can_send boolean NOT NULL DEFAULT false,PRIMARY KEY(resource_id,institution_id),CHECK(NOT can_send OR can_read));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.institution_resource_grants TO authenticated; GRANT ALL ON public.institution_resource_grants TO service_role;
ALTER TABLE public.institution_resource_grants ENABLE ROW LEVEL SECURITY;
CREATE POLICY grant_manage ON public.institution_resource_grants FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.institution_resources r WHERE r.id=resource_id AND public.manages_institution_resource(r.institution_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.institution_resources r WHERE r.id=resource_id AND public.manages_institution_resource(r.institution_id)));
CREATE POLICY grant_self_read ON public.institution_resource_grants FOR SELECT TO authenticated USING(public.can_edit_institution_publication(institution_id));
CREATE FUNCTION public.can_read_institution_resource(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.institution_resources r WHERE r.id=_id AND (public.can_edit_institution_publication(r.institution_id) OR (r.status='published' AND EXISTS(SELECT 1 FROM public.institution_resource_grants g WHERE g.resource_id=r.id AND g.can_read AND public.can_edit_institution_publication(g.institution_id))))); $$;
REVOKE ALL ON FUNCTION public.can_read_institution_resource(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_institution_resource(uuid) TO authenticated;
CREATE FUNCTION public.can_send_institution_resource(_id uuid,_sender uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_edit_institution_publication(_sender) AND EXISTS(SELECT 1 FROM public.institution_resources r JOIN public.institution_resource_grants g ON g.resource_id=r.id WHERE r.id=_id AND r.status='published' AND g.institution_id=_sender AND g.can_read AND g.can_send); $$;
REVOKE ALL ON FUNCTION public.can_send_institution_resource(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_send_institution_resource(uuid,uuid) TO authenticated;
CREATE POLICY resource_assigned_read ON public.institution_resources FOR SELECT TO authenticated USING(public.can_read_institution_resource(id));
CREATE POLICY editorial_assigned_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='institution-publications' AND EXISTS(SELECT 1 FROM public.institution_resources r WHERE r.file_path=storage.objects.name AND public.can_read_institution_resource(r.id)));
CREATE OR REPLACE FUNCTION public.public_institution_resources() RETURNS TABLE(id uuid,institution_id uuid,institution_name text,logo_path text,kind text,title text,content jsonb,file_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.institution_id,i.name,i.logo_path,r.kind,r.title,r.content,r.file_path FROM public.institution_resources r JOIN public.institutions i ON i.id=r.institution_id WHERE r.status='published' AND r.visibility='public' ORDER BY r.updated_at DESC LIMIT 200; $$;
CREATE FUNCTION public.guard_resource_visibility() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.visibility<>'restricted' THEN RAISE EXCEPTION 'New resources must be private'; END IF; IF TG_OP='UPDATE' AND NEW.visibility IS DISTINCT FROM OLD.visibility AND NOT public.manages_institution_resource(NEW.institution_id) THEN RAISE EXCEPTION 'Director required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER resource_visibility_guard BEFORE INSERT OR UPDATE ON public.institution_resources FOR EACH ROW EXECUTE FUNCTION public.guard_resource_visibility();
CREATE FUNCTION public.resource_permission_institutions() RETURNS TABLE(id uuid,name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT(coalesce(public.has_role(auth.uid(),'admin'),false) OR EXISTS(SELECT 1 FROM public.institution_members m WHERE m.user_id=auth.uid() AND public.manages_institution_resource(m.institution_id))) THEN RAISE EXCEPTION 'Director required'; END IF; RETURN QUERY SELECT i.id,i.name FROM public.institutions i ORDER BY i.name; END $$;
REVOKE ALL ON FUNCTION public.resource_permission_institutions() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.resource_permission_institutions() TO authenticated;
CREATE TABLE public.institution_whatsapp_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES public.institutions(id),label text NOT NULL CHECK(length(label) BETWEEN 3 AND 100),phone text NOT NULL CHECK(phone ~ '^[1-9][0-9]{7,14}$'),institutional_adult_confirmed boolean NOT NULL CHECK(institutional_adult_confirmed),consented_at timestamptz NOT NULL,unsubscribed_at timestamptz,UNIQUE(institution_id,phone));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.institution_whatsapp_contacts TO authenticated; GRANT ALL ON public.institution_whatsapp_contacts TO service_role;
ALTER TABLE public.institution_whatsapp_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_manager ON public.institution_whatsapp_contacts FOR ALL TO authenticated USING(public.manages_institution_resource(institution_id)) WITH CHECK(public.manages_institution_resource(institution_id));